CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

CREATE COLLATION case_insensitive (LOCALE = 'und-u-ks-level2',
    PROVIDER = icu,
    DETERMINISTIC = False
);

CREATE TABLE "Projects" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) COLLATE case_insensitive NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    CONSTRAINT "PK_Projects" PRIMARY KEY ("Id")
);

CREATE TABLE "TimeEntries" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "WorkDate" date NOT NULL,
    "ProjectId" integer NOT NULL,
    "Description" character varying(500) NOT NULL,
    "Minutes" integer NOT NULL,
    "Note" character varying(500),
    "IsCancelled" boolean NOT NULL DEFAULT FALSE,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_TimeEntries" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_TimeEntries_Minutes" CHECK ("Minutes" > 0 AND "Minutes" <= 480),
    CONSTRAINT "FK_TimeEntries_Projects_ProjectId" FOREIGN KEY ("ProjectId") REFERENCES "Projects" ("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX "IX_Projects_Name" ON "Projects" ("Name");

CREATE INDEX "IX_TimeEntries_ProjectId" ON "TimeEntries" ("ProjectId");

CREATE INDEX "IX_TimeEntries_WorkDate" ON "TimeEntries" ("WorkDate");

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20261118071702_InitialCreate', '8.0.11');

COMMIT;

